const scores = { ada: 9 };
const seen = [];

const tracked = new Proxy(scores, {
  get(target, key, receiver) {
    seen.push(key);
    return Reflect.get(target, key, receiver);
  },
});

scores.bo = 7;
console.log(tracked.bo);

tracked.cy = tracked.ada + 1;
console.log(scores.cy);
console.log(seen.join(","));
